// Eligibility screen ported from the Autonomous Job Kit (lib/jobkit/eligibility.py): the kit's own test
// cases, a parity table against results the Python produced, and the full parity fixtures
// (tests/fixtures/jobkit/eligibility/parity.json and postings.json, generated by running the Python).
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const EL = require('../../packages/core/eligibility');

const FIX = path.join(__dirname, '..', 'fixtures', 'jobkit', 'eligibility');
const PARITY = JSON.parse(fs.readFileSync(path.join(FIX, 'parity.json'), 'utf8'));
const POSTINGS = JSON.parse(fs.readFileSync(path.join(FIX, 'postings.json'), 'utf8')).postings;
const TODAY = PARITY.today; // 2026-11-16
const PROFILES = PARITY.profiles; // the kit's test profiles plus a few more; NONE is null, EMPTY is {}
const {
  F1: PROFILE_F1, F1_FINAL: PROFILE_F1_FINAL, US_CIT: PROFILE_US_CITIZEN, CA_STUDY: PROFILE_CA_STUDY,
  CA_CIT: PROFILE_CA_CITIZEN, CA_UNKNOWN: PROFILE_CA_UNKNOWN, UK_VISA: PROFILE_UK_VISA, UK_SETTLED: PROFILE_UK_SETTLED,
} = PROFILES;

const s = (text, profile, role = 'Software Engineering Intern', location = 'Austin, TX') =>
  EL.screen(text, profile, { role, location, today: TODAY }).screen;

// Python's user_status keys, for comparing with the fixtures.
const snake = (st) => ({
  auth_country: st.authCountry, citizen_of: st.citizenOf, pr_of: st.prOf, temporary_in: st.temporaryIn, f1: st.f1,
  work_authorized: st.workAuthorized, needs_sponsorship: st.needsSponsorship,
  needs_sponsorship_internship: st.needsSponsorshipInternship, degree_level: st.degreeLevel, student: st.student,
  final_year: st.finalYear, details: st.details,
});

// ---- the kit's EligibilityTests ------------------------------------------------------------------------------

test('kit: US rules', () => {
  assert.equal(s('Applicants must be U.S. citizens.', PROFILE_F1), 'skip');
  assert.equal(s('Applicants must be U.S. citizens.', PROFILE_US_CITIZEN), 'ok');
  assert.equal(s('Must be a U.S. citizen or authorized to work in the United States.', PROFILE_F1), 'ok');
  assert.equal(s('We are unable to consider candidates on F-1 OPT or CPT for this role.', PROFILE_F1), 'skip');
  assert.equal(s('Candidates on F-1 OPT/CPT are welcome to apply.', PROFILE_F1), 'ok');
  assert.equal(s('Due to ITAR, applicants must be U.S. persons.', PROFILE_F1), 'skip');
  assert.equal(s('US citizenship or permanent residence (green card) is required.', PROFILE_F1), 'skip');
  assert.equal(s('Ability to obtain a Secret security clearance is required.', PROFILE_F1, 'Engineer'), 'skip');
  assert.equal(s('Ability to obtain a Secret security clearance is required.', PROFILE_US_CITIZEN, 'Engineer'), 'ok');
  assert.equal(s('US citizenship is preferred.', PROFILE_F1), 'check');
  assert.equal(s('Some positions may require U.S. citizenship.', PROFILE_F1), 'check');
});

test('kit: sponsorship and students below their final year', () => {
  const text = 'We do not sponsor visas now or in the future.';
  assert.equal(s(text, PROFILE_F1), 'ok'); // internship + needs no sponsorship for it
  assert.equal(s(text, PROFILE_F1_FINAL), 'skip'); // final year, needs sponsorship
  const below = { ...PROFILE_F1, needsSponsorshipForInternship: '' };
  assert.equal(s(text, below), 'check'); // below final year: never skipped on sponsorship
  assert.equal(s(text, PROFILE_US_CITIZEN), 'ok');
  assert.equal(s('Will you now or in the future require visa sponsorship?', PROFILE_F1_FINAL), 'ok');
});

test('kit: degree level', () => {
  assert.equal(s("Must be currently pursuing a Master's or PhD in Computer Science.", PROFILE_F1), 'skip');
  assert.equal(s("Currently pursuing a Bachelor's, Master's or PhD.", PROFILE_F1), 'ok');
  assert.equal(s('PhD students preferred.', PROFILE_F1), 'ok');
});

test('kit: Canada', () => {
  const text = 'Applicants must be Canadian citizens or permanent residents.';
  assert.equal(s(text, PROFILE_CA_STUDY, 'Co-op Student', 'Ottawa, ON'), 'skip');
  assert.equal(s(text, PROFILE_CA_UNKNOWN, 'Co-op Student', 'Ottawa, ON'), 'check');
  assert.equal(s(text, PROFILE_CA_CITIZEN, 'Co-op Student', 'Ottawa, ON'), 'ok');
  assert.equal(s('Open to Canadian citizens, permanent residents or those legally entitled to work in Canada.',
    PROFILE_CA_STUDY, 'Co-op', 'Toronto, ON'), 'ok');
  assert.equal(s('You can apply if you are: a Canadian citizen; a permanent resident of Canada.',
    PROFILE_CA_STUDY, 'cook', 'Banff, AB'), 'skip');
  assert.equal(s('Preference will be given to Canadian citizens and permanent residents.',
    PROFILE_CA_STUDY, 'Student', 'Ottawa, ON'), 'check');
});

test('kit: UK', () => {
  const loc = 'London, UK';
  assert.equal(s('You must have the right to work in the UK; we cannot offer visa sponsorship.', PROFILE_UK_VISA, 'Graduate Analyst', loc), 'skip');
  assert.equal(s('You must have the right to work in the UK.', PROFILE_UK_VISA, 'Graduate Analyst', loc), 'check');
  assert.equal(s('You must already have the right to work in the UK.', PROFILE_UK_VISA, 'Graduate Analyst', loc), 'skip');
  assert.equal(s('You must have the right to work in the UK.', PROFILE_UK_SETTLED, 'Graduate Analyst', loc), 'ok');
  const r = EL.screen('Visa sponsorship is available for this role.', PROFILE_UK_VISA, { role: 'Analyst', location: loc, today: TODAY });
  assert.equal(r.screen, 'ok');
  assert.ok(r.why.some((w) => w.includes('note')));
});

test('kit: equal-opportunity boilerplate is ignored', () => {
  const text = 'We are an equal opportunity employer and consider all applicants without regard to citizenship status ' +
    'or national origin.';
  assert.equal(s(text, PROFILE_F1), 'ok');
});

test('kit: without a profile, restrictive sentences are "check", never "skip"', () => {
  for (const profile of [null, undefined, {}]) {
    const r = EL.screen('Applicants must be U.S. citizens.', profile, { role: 'Intern', location: 'Austin, TX' });
    assert.equal(r.screen, 'check');
    assert.ok(r.check.length);
  }
  for (const c of PARITY.eligibility.filter((x) => x.profile === 'NONE' || x.profile === 'EMPTY')) {
    assert.notEqual(EL.screen(c.text, null, { role: c.role, location: c.location, today: TODAY }).screen, 'skip', c.text);
  }
});

test('kit: user status', () => {
  let st = EL.userStatus(PROFILE_F1, TODAY);
  assert.equal(st.f1, true);
  assert.equal(st.degreeLevel, 'undergraduate');
  assert.equal(st.finalYear, false);
  st = EL.userStatus(PROFILE_CA_CITIZEN, TODAY);
  assert.deepEqual(st.citizenOf, ['CA']);
});

test('kit: real postings (Job Bank who-can-apply, iCIMS US citizenship)', () => {
  const jb = POSTINGS.find((p) => p.name === 'jobbank');
  // "who can apply" includes temporary residents: no skip for a study-permit holder
  assert.equal(EL.screen(jb.description, PROFILE_CA_STUDY, { role: jb.role, location: jb.location, today: TODAY }).screen, 'ok');
  const ic = POSTINGS.find((p) => p.name === 'icims');
  const r = EL.screen(ic.description, PROFILE_F1, { role: ic.role, location: ic.location, today: TODAY });
  assert.equal(r.screen, 'skip');
  assert.ok(r.why.some((w) => w.includes('citizenship')));
  assert.equal(EL.screen(ic.description, PROFILE_US_CITIZEN, { role: ic.role, location: ic.location, today: TODAY }).screen, 'ok');
});

// ---- helpers -------------------------------------------------------------------------------------------------

test('countryCode, postingCountry and shortReason', () => {
  assert.equal(EL.countryCode('United States'), 'US');
  assert.equal(EL.countryCode('Canada'), 'CA');
  assert.equal(EL.countryCode('Great Britain'), 'UK');
  assert.equal(EL.countryCode('France'), null);
  assert.equal(EL.postingCountry('London, ON'), 'CA');
  assert.equal(EL.postingCountry('London, UK'), 'UK');
  assert.equal(EL.postingCountry('Austin, TX'), 'US');
  assert.equal(EL.postingCountry('', 'Offices across the U.S. and the UK.'), 'UK'); // tie: first of CA, UK, US
  assert.equal(EL.shortReason({ why: ['A. -> note: sponsorship mentioned as available', 'B. -> US citizenship required'] }),
    'US citizenship required');
  assert.equal(EL.shortReason({ why: ['A. -> note: sponsorship mentioned as available'] }), '');
  assert.equal(EL.shortReason({}), '');
});

test('today may be a Date or YYYY-MM-DD; graduation within a year means final year', () => {
  const p = { authCountry: 'US', workAuthDetails: 'H-1B visa', needsSponsorship: 'yes', expectedGraduation: '2027-04',
    education: [{ degree: 'B.A. Economics' }] };
  assert.equal(EL.userStatus(p, '2026-11-16').finalYear, true);
  assert.equal(EL.userStatus(p, new Date(2026, 10, 16)).finalYear, true);
  assert.equal(EL.userStatus(p, '2025-11-16').finalYear, false); // 17 months to go
  assert.equal(EL.userStatus(p, '2027-06-01').student, false); // graduated, nothing else says student
  assert.equal(EL.userStatus({ ...p, expectedGraduation: 'May 2027' }, '2026-11-16').finalYear, true);
  assert.equal(EL.userStatus({ ...p, expectedGraduation: '', education: [{ degree: 'BSc', end: '2028' }] }, '2026-11-16').finalYear, false);
  const text = 'We do not sponsor visas now or in the future.';
  assert.equal(EL.screen(text, p, { role: 'Analyst', today: '2026-11-16' }).screen, 'skip');
  assert.equal(EL.screen(text, p, { role: 'Analyst', today: '2025-11-16' }).screen, 'check');
});

test('user status reads the profile.json fields', () => {
  const st = EL.userStatus({ country: 'Canada', workAuthDetails: 'PGWP until 2027-05-01', needsSponsorship: 'yes',
    needsSponsorshipForInternship: 'no', workAuthorized: 'yes', enrolled: 'no', classStanding: 'fourth year',
    education: [{ degree: 'MASc' }] }, TODAY);
  assert.deepEqual(st, {
    authCountry: 'CA', citizenOf: [], prOf: [], temporaryIn: ['CA'], f1: false, workAuthorized: true,
    needsSponsorship: true, needsSponsorshipInternship: false, degreeLevel: 'graduate', student: false, finalYear: null,
    details: 'PGWP until 2027-05-01',
  });
  const uk = EL.userStatus({ authCountry: 'United Kingdom', workAuthDetails: 'Indefinite leave to remain (ILR)' }, TODAY);
  assert.deepEqual(uk.prOf, ['UK']);
  const gc = EL.userStatus({ authCountry: 'US', workAuthDetails: 'Green card holder' }, TODAY);
  assert.deepEqual([gc.prOf, gc.citizenOf], [['US'], []]);
});

