test('parity table: same screen and reason as the Python on representative sentences', () => {
  assert.ok(TABLE.length >= 25);
  for (const [text, profile, role, location, screen, reason] of TABLE) {
    const r = EL.screen(text, PROFILES[profile], { role, location, today: TODAY });
    assert.deepEqual([r.screen, EL.shortReason(r)], [screen, reason], `${profile}: ${text}`);
  }
});

test('parity fixtures: identical screens (why, check, country) to the Python', () => {
  assert.ok(PARITY.eligibility.length >= 25);
  for (const c of PARITY.eligibility) {
    const r = EL.screen(c.text, PROFILES[c.profile], { role: c.role, location: c.location, today: TODAY });
    assert.deepEqual({ screen: r.screen, why: r.why, check: r.check, country: r.country, short: EL.shortReason(r) }, c.expected,
      `${c.profile}: ${c.text}`);
  }
});

test('parity fixtures: identical user status, country codes and posting countries', () => {
  for (const [name, profile] of Object.entries(PROFILES)) {
    assert.deepEqual(snake(EL.userStatus(profile, TODAY)), PARITY.status[name], name);
  }
  for (const c of PARITY.countryCode) assert.equal(EL.countryCode(c.value), c.expected, String(c.value));
  for (const c of PARITY.postingCountry) assert.equal(EL.postingCountry(c.location, c.text), c.expected, `${c.location}|${c.text}`);
});

test('parity fixtures: real postings screen the same as the Python for every profile', () => {
  let n = 0;
  for (const p of POSTINGS) {
    for (const [name, expected] of Object.entries(p.expected.screens)) {
      const r = EL.screen(p.description, PROFILES[name], { role: p.role, location: p.location, today: TODAY });
      assert.deepEqual({ screen: r.screen, why: r.why, check: r.check, country: r.country }, expected, `${p.name} / ${name}`);
      n++;
    }
  }
  assert.equal(n, POSTINGS.length * Object.keys(PROFILES).length);
});

test('loads as browser globals (CoreRedFlags then CoreEligibility)', () => {
  const ctx = { self: {} };
  for (const f of ['redflags', 'eligibility']) {
    vm.runInNewContext(fs.readFileSync(require.resolve(`../../packages/core/${f}`), 'utf8'), ctx);
  }
  const r = ctx.self.CoreEligibility.screen('Applicants must be U.S. citizens.', PROFILE_F1, { role: 'Intern', location: 'Austin, TX', today: TODAY });
  assert.equal(r.screen, 'skip');
});
